/* =========================================================
   RAMIS PREMIUM HERO
========================================================= */

selector {
    --ramis-primary: #006660;
    --ramis-dark: #003F3C;
    --ramis-secondary: #004F4B;
    --ramis-gold: #FFCE3A;
    --ramis-white: #FFFFFF;

    position: relative;
    isolation: isolate;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 88% 15%,
            rgba(255, 206, 58, 0.12),
            transparent 29%
        ),
        radial-gradient(
            circle at 8% 85%,
            rgba(0, 180, 165, 0.17),
            transparent 34%
        ),
        linear-gradient(
            135deg,
            var(--ramis-dark) 0%,
            var(--ramis-primary) 52%,
            #00332F 100%
        );

    border-radius: 0 0 30px 30px;

    box-shadow:
        0 18px 45px rgba(0, 45, 42, 0.14);

    z-index: 1;
}


/* =========================================================
   ATMOSPHERIC LIGHT EFFECTS
========================================================= */

selector::before {
    content: "";
    position: absolute;

    width: 380px;
    height: 380px;

    top: -210px;
    right: -120px;

    background:
        radial-gradient(
            circle,
            rgba(255, 206, 58, 0.11) 0%,
            rgba(255, 206, 58, 0.035) 35%,
            transparent 70%
        );

    filter: blur(10px);
    pointer-events: none;

    z-index: -1;
}


selector::after {
    content: "";
    position: absolute;

    width: 420px;
    height: 420px;

    bottom: -280px;
    left: -160px;

    background:
        radial-gradient(
            circle,
            rgba(0, 210, 190, 0.13) 0%,
            rgba(0, 210, 190, 0.035) 38%,
            transparent 70%
        );

    filter: blur(14px);
    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   CONTENT LAYER
========================================================= */

selector .elementor-element-d025da1,
selector .elementor-element-2a902af {
    position: relative;
    z-index: 2;
}


/* =========================================================
   TEXT CONTAINER
========================================================= */

selector .elementor-element-d025da1 {
    transition: transform .4s cubic-bezier(.2,.8,.2,1);
}


/* =========================================================
   HERO TITLE
========================================================= */

selector .elementor-element-c5c9526 {
    position: relative;
}

selector .elementor-element-c5c9526 p {
    margin: 0;

    color: var(--ramis-white) !important;

    font-size: clamp(32px, 4vw, 46px);
    font-weight: 900;
    line-height: 1.4;

    letter-spacing: -0.5px;

    text-shadow:
        0 4px 18px rgba(0, 0, 0, 0.16);
}


/* =========================================================
   GOLD ACCENT LINE
========================================================= */

selector .elementor-element-c5c9526::after {
    content: "";

    display: block;

    width: 55px;
    height: 4px;

    margin-top: 14px;

    background: var(--ramis-gold);

    border-radius: 20px;

    box-shadow:
        0 3px 12px rgba(255, 206, 58, 0.18);

    transition:
        width .4s cubic-bezier(.2,.8,.2,1),
        box-shadow .4s ease;
}


selector .elementor-element-d025da1:hover
.elementor-element-c5c9526::after {
    width: 82px;

    box-shadow:
        0 4px 16px rgba(255, 206, 58, 0.28);
}


/* =========================================================
   HERO DESCRIPTION
========================================================= */

selector .elementor-element-e53219a {
    margin-top: 10px;
}

selector .elementor-element-e53219a p {
    margin: 0;

    max-width: 620px;

    color: rgba(255, 255, 255, 0.74) !important;

    font-size: 15px;
    font-weight: 400;

    line-height: 2.15;

    transition:
        color .35s ease;
}


selector .elementor-element-d025da1:hover
.elementor-element-e53219a p {
    color: rgba(255, 255, 255, 0.86) !important;
}


/* =========================================================
   IMAGE CONTAINER
========================================================= */

selector .elementor-element-2a902af {
    position: relative;

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1);
}


/* =========================================================
   PREMIUM IMAGE FRAME
========================================================= */

selector .elementor-element-2a902af::before {
    content: "";

    position: absolute;

    inset: 9px -9px -9px 9px;

    border: 1px solid rgba(255, 206, 58, 0.30);

    border-radius: 23px;

    background:
        linear-gradient(
            135deg,
            rgba(255, 206, 58, 0.06),
            transparent 55%
        );

    pointer-events: none;

    z-index: -1;

    transition:
        border-color .4s ease,
        transform .45s cubic-bezier(.2,.8,.2,1);
}


/* =========================================================
   IMAGE WIDGET
========================================================= */

selector .elementor-element-1702712 {
    position: relative;

    overflow: hidden;

    border-radius: 20px;

    border: 1px solid rgba(255, 255, 255, 0.15);

    background: rgba(255, 255, 255, 0.04);

    box-shadow:
        0 25px 55px rgba(0, 0, 0, 0.28);

    transform: rotate(2deg);

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1),
        box-shadow .4s ease,
        border-color .4s ease;
}


/* =========================================================
   IMAGE
========================================================= */

selector .elementor-element-1702712 img {
    display: block;

    width: 100%;
    height: auto;

    border-radius: 19px;

    transition:
        transform .55s cubic-bezier(.2,.8,.2,1),
        filter .4s ease;
}


/* =========================================================
   IMAGE HOVER
========================================================= */

selector .elementor-element-2a902af:hover
.elementor-element-1702712 {
    transform:
        rotate(0deg)
        translateY(-7px);

    border-color: rgba(255, 206, 58, 0.28);

    box-shadow:
        0 30px 65px rgba(0, 0, 0, 0.34);
}


selector .elementor-element-2a902af:hover::before {
    border-color: rgba(255, 206, 58, 0.48);

    transform:
        translate(-2px, 2px);
}


selector .elementor-element-2a902af:hover
.elementor-element-1702712 img {
    transform: scale(1.025);
}


/* =========================================================
   TABLET
   768px – 1024px
========================================================= */

@media (min-width: 768px) and (max-width: 1024px) {

    selector {
        border-radius: 0 0 26px 26px;
    }

    selector .elementor-element-c5c9526 p {
        font-size: clamp(30px, 4.5vw, 40px);
    }

    selector .elementor-element-e53219a p {
        font-size: 14px;
        line-height: 2;
    }

    selector .elementor-element-1702712 {
        transform: rotate(1.5deg);
    }

    selector .elementor-element-2a902af::before {
        inset: 7px -7px -7px 7px;
    }
}


/* =========================================================
   MOBILE
   Below 767px
========================================================= */

@media (max-width: 767px) {

    selector {
        border-radius: 0 0 22px 22px;

        background:
            radial-gradient(
                circle at 90% 10%,
                rgba(255, 206, 58, 0.09),
                transparent 32%
            ),
            radial-gradient(
                circle at 10% 90%,
                rgba(0, 180, 165, 0.12),
                transparent 35%
            ),
            linear-gradient(
                145deg,
                #003F3C 0%,
                #006660 55%,
                #00332F 100%
            );
    }


    /* Reduce decorative glow */

    selector::before {
        width: 260px;
        height: 260px;

        top: -160px;
        right: -100px;

        filter: blur(14px);
    }

    selector::after {
        width: 280px;
        height: 280px;

        bottom: -190px;
        left: -120px;

        filter: blur(16px);
    }


    /* Center the text */

    selector .elementor-element-d025da1 {
        text-align: center;
    }


    /* Title */

    selector .elementor-element-c5c9526 p {
        font-size: clamp(28px, 8vw, 36px);

        line-height: 1.5;

        letter-spacing: 0;

        text-shadow:
            0 3px 14px rgba(0, 0, 0, 0.14);
    }


    /* Gold line */

    selector .elementor-element-c5c9526::after {
        width: 48px;

        margin: 12px auto 0;
    }


    selector .elementor-element-d025da1:hover
    .elementor-element-c5c9526::after {
        width: 68px;
    }


    /* Description */

    selector .elementor-element-e53219a {
        margin-top: 9px;
    }

    selector .elementor-element-e53219a p {
        max-width: 100%;

        font-size: 14px;

        line-height: 2.05;

        color: rgba(255, 255, 255, 0.75) !important;
    }


    /* Image */

    selector .elementor-element-2a902af {
        margin-top: 12px;
    }

    selector .elementor-element-1702712 {
        transform: none;

        border-radius: 17px;

        box-shadow:
            0 18px 40px rgba(0, 0, 0, 0.25);
    }

    selector .elementor-element-1702712 img {
        border-radius: 16px;
    }


    /* Smaller image frame */

    selector .elementor-element-2a902af::before {
        inset: 6px -6px -6px 6px;

        border-radius: 20px;
    }


    /* Disable image movement on mobile */

    selector .elementor-element-2a902af:hover
    .elementor-element-1702712 {
        transform: translateY(-4px);
    }

    selector .elementor-element-2a902af:hover::before {
        transform: none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    selector *,
    selector *::before,
    selector *::after {
        transition: none !important;
        animation: none !important;
    }

    selector .elementor-element-1702712,
    selector .elementor-element-2a902af:hover
    .elementor-element-1702712 {
        transform: none !important;
    }
}

/* حذف کامل بکگراند عکس */
.elementor-widget-image,
.elementor-widget-image .elementor-widget-container,
.elementor-widget-image img {
    background: transparent !important;
    background-color: transparent !important;
}

/* اطمینان از شفاف بودن خود تصویر */
.elementor-widget-image img {
    mix-blend-mode: normal !important;
}

/* =================================
   Sidebar Popular Posts Only
================================= */


.sidebar-popular-posts .elementor-posts-container {
    display: flex;
    flex-direction: column;
    gap: 16px;
}


.sidebar-popular-posts .elementor-post {
    background: #fff;
    border: 1px solid rgba(0,0,0,.06);
    border-radius: 18px;
    padding: 12px;
    display: flex;
    gap: 14px;
    align-items: center;
    overflow: hidden;
    position: relative;

    transition:
        transform .35s ease,
        box-shadow .35s ease,
        border-color .35s ease;
}


/* خط کناری */
.sidebar-popular-posts .elementor-post::before {
    content:"";
    position:absolute;
    right:0;
    top:0;
    width:4px;
    height:100%;

    background:linear-gradient(
        180deg,
        #006660,
        #c9a227
    );

    transform:scaleY(0);
    transition:.35s ease;
}


/* تصویر */
.sidebar-popular-posts .elementor-post__thumbnail__link {
    flex:0 0 82px;
}


.sidebar-popular-posts .elementor-post__thumbnail {
    width:82px;
    height:82px;
    border-radius:14px;
    overflow:hidden;
}


.sidebar-popular-posts .elementor-post__thumbnail img {
    width:100%;
    height:100%;
    object-fit:cover;
}



/* عنوان */
.sidebar-popular-posts .elementor-post__title {
    margin:0 0 8px !important;
    line-height:1.8;
}


.sidebar-popular-posts .elementor-post__title a {
    color:#006660;
    font-size:14px;
    font-weight:700;
    transition:.3s ease;
}



/* متا */
.sidebar-popular-posts .elementor-post-date,
.sidebar-popular-posts .elementor-post-avatar {
    font-size:11px;
    color:#888;
}


/* حذف مطالعه بیشتر */
.sidebar-popular-posts .elementor-post__read-more {
    display:none;
}



/* Hover فقط کارت */
.sidebar-popular-posts .elementor-post:hover {

    transform:translateY(-3px);

    border-color:rgba(201,162,39,.35);

    box-shadow:
    0 12px 30px rgba(0,0,0,.08);
}


.sidebar-popular-posts .elementor-post:hover::before {
    transform:scaleY(1);
}


.sidebar-popular-posts .elementor-post:hover .elementor-post__title a {
    color:#004d4a;
}



/* موبایل */
@media(max-width:767px){

.sidebar-popular-posts .elementor-post{
    padding:10px;
}

.sidebar-popular-posts .elementor-post__thumbnail,
.sidebar-popular-posts .elementor-post__thumbnail__link{
    width:70px;
    height:70px;
}

}

/* =================================
   Tablet Optimization
================================= */

@media (min-width: 768px) and (max-width: 1024px) {

    .sidebar-popular-posts .elementor-post {
        padding: 10px;
        gap: 10px;
        border-radius: 15px;
    }

    .sidebar-popular-posts .elementor-post__thumbnail__link {
        flex: 0 0 68px;
        width: 68px;
        height: 68px;
    }

    .sidebar-popular-posts .elementor-post__thumbnail {
        width: 68px;
        height: 68px;
        border-radius: 12px;
    }

    .sidebar-popular-posts .elementor-post__title {
        margin-bottom: 5px !important;
        line-height: 1.6;
    }

    .sidebar-popular-posts .elementor-post__title a {
        font-size: 13px;
    }

    .sidebar-popular-posts .elementor-post-date,
    .sidebar-popular-posts .elementor-post-avatar {
        font-size: 10px;
    }

}

